microphone.usage:
// Public API of Microphone — the instance is `{{ instance }}`.
// begin() ran in setup() and started a background capture task, so the level
// getters below return the latest cached value instantly (never block). If you
// leave loop empty, the module already streams a `level` event every 250 ms.

// --- sound level / detection ---
int16_t level = {{ instance }}.getSoundLevel();          // RMS, 0..32767
if ({{ instance }}.isSoundDetected(500)) { /* above threshold */ }
int16_t peak = {{ instance }}.getPeakAmplitude();        // peak since last read (resets)

// --- raw samples (max BUFFER_SAMPLES = 512 per call) ---
int16_t buf[512];
int n = {{ instance }}.getSamples(buf, 512);

// --- record to a heap buffer (up to ~3 s at 16 kHz), then play back ---
{{ instance }}.startRecording();
// ... let time pass in your loop (non-blocking) ...
{{ instance }}.stopRecording();
const int16_t* rec = {{ instance }}.getRecording();      // MUST be const
int len = {{ instance }}.getRecordingLength();           // sample count
// Pair with a speaker on another port for playback: spk.writeSamples(rec, len);

