robot_arm.usage:
// Public API of RobotArm — the instance is `{{ instance }}`.
// begin() + setTorqueAll(true) ran in setup(). Positions are 0-4095
// (center 2048, ≈0-240°); joint IDs are 1-6.
// POWER: the servos get whatever supply is plugged into the power jack module
// (board high-voltage rail, unregulated; the standard USB-C module does not feed it). Match it to the
// arm: 12 V supply for a 12 V arm, 5 V for a 5 V arm. 12 V on a 5 V arm damages it.

// --- move ---
{{ instance }}.moveJoint(1, 2048, 800);           // joint 1 -> center over 800 ms
uint16_t pose[6] = {2048,2048,2048,2048,2048,2048};
{{ instance }}.moveAll(pose, 1000);               // synchronized move (uint16_t[6]!)
{{ instance }}.centerAll(1000);                   // all joints to 2048

// --- read (declare position buffers as uint16_t[6], NOT int[]) ---
uint16_t pos[6];
int ok = {{ instance }}.readAll(pos);             // returns count of good reads
int p1 = {{ instance }}.readJoint(1);             // 0-4095, or -1 on error
int tC = {{ instance }}.readTemperature(1);       // °C, -1 on error

// --- torque ---
{{ instance }}.setTorque(3, false);               // release one joint (hand-pose it)
{{ instance }}.setTorqueAll(true);

// --- record a motion, then replay it ---
{{ instance }}.startRecording(100);               // capture every 100 ms
// call {{ instance }}.captureFrame(); each loop while recording, then:
{{ instance }}.stopRecording();
{{ instance }}.playRecording(100);                // 100 = normal, 50 = half, 200 = double
{{ instance }}.saveToSlot(0);                     // persist to flash (slots 0-9)
{{ instance }}.loadFromSlot(0);

