// Public API of SCD40 — the instance is `{{ instance }}`.
// begin() ran in setup() and started a background polling task, so the
// getters below return the latest cached value instantly (no blocking).
// If you leave loop empty, the module already streams co2 + temperature +
// humidity events every 5 s — only add code here for custom behaviour.
uint16_t ppm = {{ instance }}.readCO2();           // 0 until first reading
float c      = {{ instance }}.readTemperature();   // degrees Celsius
float rh     = {{ instance }}.readHumidity();      // % relative humidity

// readCO2() returns 0 for the first ~5 s. Guard any UI with isReady():
if ({{ instance }}.isReady()) { /* a real measurement has landed */ }
if ({{ instance }}.isConnected()) { /* sensor is responding on the bus */ }

// The sensor only updates every 5 s — polling faster just re-reads the
// same cached value. Indoor CO2 reference:
//   <800 ppm fresh | 800-1200 acceptable | >1500 poor | >2000 uncomfortable
//
// Edge-trigger with hysteresis so it fires once per crossing, not every loop:
//   static bool stuffy = false;
//   if (!stuffy && ppm > 1200) { stuffy = true;  /* crossed into poor air */ }
//   else if (stuffy && ppm < 1000) { stuffy = false; /* recovered */ }

speaker.usage:
// Public API of Speaker — the instance is `{{ instance }}`.
// Audio runs in a background task: every call below returns immediately.
// begin() + setVolume(0.4f) already ran in setup(); don't play on boot.
//
// NOTE_* frequency constants are provided by speaker.h, octaves 3-6:
//   NOTE_C4, NOTE_CS4 (C#), NOTE_D4 ... NOTE_B4, NOTE_C5 ... NOTE_B6, NOTE_REST
// Comfortable range is NOTE_C4..NOTE_B5 (~260-990 Hz). Above NOTE_C6 gets piercing.

// --- single tone: one sine wave, auto-stops after durationMs ---
{{ instance }}.playTone(NOTE_A4, 200);             // 440 Hz for 200 ms
{{ instance }}.playTone(880, 50);                  // raw Hz also fine

// --- melodies: call playNote() back-to-back (15% gap between notes) ---
{{ instance }}.playNote(NOTE_C5, 90);              // success motif:
{{ instance }}.playNote(NOTE_E5, 90);              //   C - E - G
{{ instance }}.playNote(NOTE_G5, 120);

// --- chords: up to 6 simultaneous frequencies ---
float triad[] = { NOTE_C4, NOTE_E4, NOTE_G4 };
{{ instance }}.playChord(triad, 3, 400);

// --- RTTTL: play a whole ringtone/jingle from one string (non-blocking) ---
{{ instance }}.playRTTTL("scale:d=4,o=5,b=160:c,d,e,f,g,a,b,2c6");

// --- control ---
{{ instance }}.setVolume(0.5f);                    // 0.0 .. 1.0 (1.0 clips)
if ({{ instance }}.isPlaying()) { /* still sounding */ }
{{ instance }}.stop();                             // silence immediately

// GUIDELINES (important for good-sounding firmware):
//  - Prefer short 2-4 note playNote() motifs over bare sustained tones.
//  - Only play in response to events; never call playTone() unguarded in loop().
//  - Do NOT play on boot. Keep tone durations <= ~2000 ms.
//  - Never use Arduino tone()/noTone() — they don't drive I2S.

st7735_tft.usage:
// Public API of ST7735_TFT — the instance is `{{ instance }}`. 160x80 px.
// begin() + clear() already ran in setup(). Colour constants live on the
// class: ST7735_TFT::COLOR_BLACK / _WHITE / _RED / _GREEN / _BLUE / _CYAN /
// _MAGENTA / _YELLOW / _ORANGE  (RGB565 uint16_t — raw values also accepted).

// --- CANVAS MODE (default): clear -> draw -> display. Flicker-free. ---
{{ instance }}.clear();
{{ instance }}.setCursor(4, 4);
{{ instance }}.setTextSize(1);
{{ instance }}.setTextColor(ST7735_TFT::COLOR_WHITE);
{{ instance }}.print("Hello");                 // print() takes ONE arg only
{{ instance }}.displayText("42C", 4, 30, 2, ST7735_TFT::COLOR_RED); // text+pos+size+colour
{{ instance }}.display();                       // push the frame to the screen

// --- ANIMATION: display() pushes all 160x80 px (25.6 kB) over SOFTWARE SPI
// and costs ~270 ms. Do NOT call it every frame -- you will watch the panel
// repaint. Instead paint the static backdrop once, then push only the box
// that changed (cost scales with area: a 44x52 box is ~16x cheaper, ~17 ms):
{{ instance }}.displayRegion(x, y, w, h);       // push ONLY this rectangle
// Repaint the box spanning the sprite's OLD and NEW positions so the old
// one is erased in the same push. ~30 fps is achievable this way.

// Software SPI clock (default 40 MHz). Lower it for screens on noisy pins
// -- on ESP32-S3, GPIO 33-37 share the octal flash/PSRAM bank:
{{ instance }}.setSPISpeed(10000000);

// --- shapes ---
{{ instance }}.fillScreen(ST7735_TFT::COLOR_BLACK);
{{ instance }}.drawRect(10, 10, 40, 20, ST7735_TFT::COLOR_GREEN);
{{ instance }}.fillRect(10, 10, 40, 20, ST7735_TFT::COLOR_BLUE);
{{ instance }}.drawCircle(80, 40, 15, ST7735_TFT::COLOR_YELLOW);
{{ instance }}.fillCircle(80, 40, 15, ST7735_TFT::COLOR_CYAN);
{{ instance }}.drawLine(0, 0, 159, 79, ST7735_TFT::COLOR_WHITE);
{{ instance }}.drawPixel(5, 5, ST7735_TFT::COLOR_RED);

// --- DIRECT MODE (games/animation): set once in setup, then never call ---
// clear()/fillScreen()/display() in the loop. Erase old position with a
// small fillRect(bg), then draw at the new position.
{{ instance }}.setDirectMode(true);

int16_t w = {{ instance }}.width();             // 160
int16_t h = {{ instance }}.height();            // 80
{{ instance }}.setRotation(1);                   // 0-3

// To position text: setCursor(x,y) THEN print(value) — never pass coords to print().

stepper_motor.usage:
// Public API of StepperMotor — the instance is `{{ instance }}`.
// begin() already ran in setup(); the motor starts DISABLED (coils released).
// All moves are BLOCKING and auto-enable the driver. stepsPerSecond is
// clamped to [1, 20000]; 200-2000 is smooth. Position is in microsteps,
// counted from power-on / resetPosition() — there is no homing switch.

// --- relative moves ---
{{ instance }}.moveSteps(1600, 800);     // +1600 microsteps fwd @ 800 sps (~1 rev at 1/8)
{{ instance }}.moveSteps(-800, 1200);    // reverse 800 microsteps

// --- direction-then-step ---
{{ instance }}.setDirection(true);       // true = forward
{{ instance }}.step(400, 600);           // 400 microsteps in current direction

// --- absolute positioning (relative to resetPosition/power-on) ---
{{ instance }}.resetPosition();          // call at a known mechanical reference
{{ instance }}.moveTo(3200, 1000);       // go to absolute position 3200
int32_t pos = {{ instance }}.getPosition();

// --- power / config ---
{{ instance }}.enable();                 // energise coils (holding torque)
{{ instance }}.disable();                // release coils when idle (saves heat/power)
{{ instance }}.setReversed(true);        // flip what "forward" means for this motor

// Never digitalWrite() the STEP/DIR/ENABLE pins directly — use these methods.
